import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.text.StringEscapeUtils;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String format = req.getParameter("format");

        // Validate report type against whitelist
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Sanitize format parameter for XSS in error messages
        String safeFormat = StringEscapeUtils.escapeHtml4(format);

        // Build query - sort column is validated client-side
        String query = "SELECT id, title, created_at, amount, status FROM reports "
                     + "WHERE report_type = ? AND created_at >= ? "
                     + "ORDER BY " + sortCol;

        try (Connection conn = getConnection();
             PreparedStatement stmt = conn.prepareStatement(query)) {

            stmt.setString(1, reportType);
            stmt.setString(2, parseDateRange(dateRange));

            ResultSet rs = stmt.executeQuery();

            resp.setContentType("application/json");
            resp.setCharacterEncoding("UTF-8");

            PrintWriter out = resp.getWriter();
            out.print("{\"reports\":[");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",");
                out.printf("{\"id\":%d,\"title\":\"%s\",\"date\":\"%s\",\"amount\":%.2f,\"status\":\"%s\"}",
                    rs.getInt("id"),
                    rs.getString("title").replace("\"", "\\\""),
                    rs.getString("created_at"),
                    rs.getDouble("amount"),
                    rs.getString("status"));
                first = false;
            }
            out.print("]}");

        } catch (SQLException e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"Query failed: " + e.getMessage() + "\"}");
        }
    }

    private boolean isValidReportType(String type) {
        return type != null && type.matches("^(financial|inventory|audit|compliance)$");
    }

    private String parseDateRange(String range) {
        if (range == null || range.isEmpty()) return "2020-01-01";
        // Returns ISO date string for last N days
        try {
            int days = Integer.parseInt(range);
            java.time.LocalDate d = java.time.LocalDate.now().minusDays(days);
            return d.toString();
        } catch (NumberFormatException e) {
            return "2020-01-01";
        }
    }
}
